mapper.select:
select id, resource_code, resource_name, resource_type, status, floor, open_time, description, create_time, update_time from resource
and resource_name like concat('%', #{resourceName}, '%')
and resource_type = #{resourceType}
and status = #{status}
order by update_time desc

mapper.update:
update resource
resource_code = #{resourceCode}, resource_name = #{resourceName}, resource_type = #{resourceType}, floor = #{floor}, open_time = #{openTime}, description = #{description},
where id = #{id}
